const items = $input.all();
const data = items[0].json.body;

const revenue = parseFloat(data.revenue) || 0;
const cogs = parseFloat(data.costOfGoodsSold) || 0;
const operatingExpenses = parseFloat(data.operatingExpenses) || 0;
const totalAssets = parseFloat(data.totalAssets) || 1;
const totalLiabilities = parseFloat(data.totalLiabilities) || 0;
const equity = parseFloat(data.equity) || 1;
const currentAssets = parseFloat(data.currentAssets) || 0;
const currentLiabilities = parseFloat(data.currentLiabilities) || 1;
const netIncome = parseFloat(data.netIncome) || 0;
const inventory = parseFloat(data.inventory) || 0;
const cashFlow = parseFloat(data.operatingCashFlow) || 0;

const ratios = {
  profitability: {
    grossMargin: revenue > 0 ? ((revenue - cogs) / revenue * 100).toFixed(2) + '%' : 'N/A',
    operatingMargin: revenue > 0 ? ((revenue - cogs - operatingExpenses) / revenue * 100).toFixed(2) + '%' : 'N/A',
    netMargin: revenue > 0 ? (netIncome / revenue * 100).toFixed(2) + '%' : 'N/A',
    returnOnAssets: (netIncome / totalAssets * 100).toFixed(2) + '%',
    returnOnEquity: (netIncome / equity * 100).toFixed(2) + '%'
  },
  liquidity: {
    currentRatio: (currentAssets / currentLiabilities).toFixed(2),
    quickRatio: ((currentAssets - inventory) / currentLiabilities).toFixed(2),
    cashRatio: currentLiabilities > 0 ? (cashFlow / currentLiabilities).toFixed(2) : 'N/A'
  },
  leverage: {
    debtToEquity: (totalLiabilities / equity).toFixed(2),
    debtToAssets: (totalLiabilities / totalAssets * 100).toFixed(2) + '%',
    equityMultiplier: (totalAssets / equity).toFixed(2)
  },
  efficiency: {
    assetTurnover: (revenue / totalAssets).toFixed(2),
    inventoryTurnover: inventory > 0 ? (cogs / inventory).toFixed(2) : 'N/A'
  }
};

return [{
  json: {
    company: data.company || 'Unknown',
    period: data.period || new Date().toISOString().split('T')[0],
    ratios,
    rawData: {
      revenue, cogs, operatingExpenses, totalAssets,
      totalLiabilities, equity, currentAssets, currentLiabilities,
      netIncome, inventory, cashFlow
    }
  }
}];
